760	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
761	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
762	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
763	    //
764	    //    DETERMINISM — FIXED-PARTITION reduction (mirrors the A/A/A-CLEAN GrokAdamW
765	    //    P2.5 grad-norm reduce above), NOT the work-steal task-queue drain. WHY THIS
766	    //    SHAPE: the previous form drained the global TaskQueue (q.next_block →
767	    //    atomicAdd(g_next_task)) inside phaseA and reset that SAME counter in a
768	    //    sync_RESET barrier (B2.6a). The work-steal claim order is timing-dependent,
769	    //    so each CTA's (r,s) slot holds a potentially DIFFERENT tensor subset run-to-
770	    //    run; because fp32 add is non-associative, the per-CTA partials then regroup
771	    //    the same values differently and the owner's d can differ at ULP level from
772	    //    step>=2 (a COMPONENT_CONTRACT deterministic-reduction violation — even where
773	    //    it happens to be empirically bit-exact on a given GPU/workload, it is not
774	    //    deterministic BY CONSTRUCTION). GrokAdamW's P2.5 reduces a FIXED contiguous
775	    //    element range per CTA with a plain sync() and is A/A/A-CLEAN; prodigy now
776	    //    uses the IDENTICAL shape — deterministic by construction, independent of CTA
777	    //    timing. Each CTA owns [e0,e0+ecnt) of the FLAT [0,total) arrays —
778	    //    params/param_init/grad are parallel flat blobs, so a contiguous flat range
779	    //    sum == the cross-all-TENSORS sum (tensor boundaries are irrelevant to a
780	    //    global Σ). The per-element contribution still CALLS the canonical
781	    //    prodigy_partials_step (prodigy.h:28-53, single-source). NO float atomic;
782	    //    per-CTA (r,s) slot publish → ONE plain grid barrier → CTA0 owner-sums
783	    //    ascending → EMA-decay/update_d → broadcast → ONE plain grid barrier.
784	    //    g_next_task is UNTOUCHED here (B2 already reset it to 0), so P3's queue
785	    //    drain runs unchanged — no sync_reset needed in P2.6.
786	    //    Guarded so every other opt's P3 is byte-identical (no extra barrier/work).
787	    if constexpr (Opt == OptId::Prodigy) {
788	        // Per-CTA (r,s) slots in opt_reduce ([r slots | s slots]) + the reduced-d
789	        // broadcast slot. d_prev: persisted d_lr (slot 2), or d0 cold-start at step 1.
790	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
791	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
792	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
793	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
794	        // FIXED contiguous element range over the flat [0,total_p) arrays (same split
795	        // as GrokAdamW P2.5: even base + remainder to the low CTAs → deterministic).
796	        const int64_t total_p = kDecTotalElems;
797	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
798	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
799	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
800	        float r_acc = 0.0f, s_acc = 0.0f;
801	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
802	            // Canonical per-element partials (prodigy.h:28-53): r carries d²·<g,p0−p>,
803	            // s carries d²·|g| (the L1-norm denominator). params/param_init/grad are
804	            // flat blobs → index pe0+i is the same element in all three.
805	            algo::prodigy_partials_step(params, st.param_init, grad,
806	                                        d_prev, pe0 + i, r_acc, s_acc);
807	        }
808	        // Deterministic in-CTA two-value reduction (fixed thread count) → thread0
809	        // publishes this CTA's (r,s) slot. No atomic.
810	        float r_block, s_block;
811	        prim::block_reduce_sum2_f32(r_acc, s_acc, r_block, s_block);
812	        if (threadIdx.x == 0) { r_part[cta] = r_block; s_part[cta] = s_block; }
813	        bar.sync();   // B2.6a: all per-CTA (r,s) partials published & visible
814	        // Owner block (CTA0 thread0): ascending owner-sum + EMA decay + accumulate +
815	        // d_coef + update_d, byte-matching launch_multi_tensor_prodigy_fused_reduce_step.
816	        if (cta == 0 && threadIdx.x == 0) {
817	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
818	            for (int c = 0; c < nCTA; ++c) { r_step += r_part[c]; s_step += s_part[c]; }
819	            // Decay persisted scalars by beta3, then add this step's reduction.
820	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
821	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
822	            // d = max(d_prev, d_coef·r_ema/|s_ema|). prodigy_update_d does
823	            // max(d_prev, r/|s|) verbatim, so fold d_coef into the numerator copy
824	            // (persisted r_ema stays UNSCALED — returned/persisted, eager parity).
825	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
826	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
827	            st.prodigy_persist[1] = s_ema;
828	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
829	            d_bc[0]               = d_new;          // broadcast to all CTAs
830	        }
831	        bar.sync();   // B2.6b: d visible to every CTA before the apply
832	        st.d_factor = d_bc[0];                      // the reduced d the tail reads
833	    }
834	
835	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
836	    //    2D weights (INTEGRATION-OPTSTAGES §3). IDENTICAL to the vit twin
837	    //    (fused_vit_megakernel.cuh P2.7) — same shared opt_stages_precompute.cuh
838	    //    helpers, same barrier sequence — only the per-model 2D table (dectc::
839	    //    kDecMuon2D, 11 matrices including tok[99,128]/pos[4,128]) and offset array
840	    //    (kDecOffsets) differ. For EACH 2D matrix all CTAs cooperate: buf=μ·buf+g
841	    //    (buf is the PERSISTENT m-slice — momentum state, NOT transient), ‖buf‖_F via
842	    //    per-CTA partials → inv_norm, X=buf·inv_norm, then ns_steps × { A=XXᵀ → AX=A·X
843	    //    → AAX=A·AX → orth=a·X+b·AX+c·AAX, swap }, then the canonical muon_update_step
844	    //    apply (decay·p + neg_lr_scale·orth). The 1D / non-2D weights (biases, LN γ/β)
845	    //    take the AdamW aux tail in P3. The elementwise bodies CALL muon.h
846	    //    (muon_momentum_normalize_step via the phaseA buf body, muon_ns_combine_step,
847	    //    muon_update_step); the matmuls are the cited new device code (the eager path
848	    //    delegates to torch::mm/cuBLAS). Guarded so every other opt is byte-identical
849	    //    (no extra barriers / work).
850	    if constexpr (Opt == OptId::Muon) {
851	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
852	        PrecomputeWorkspace pw{};
853	        pw.muon_X            = muon_base;
854	        pw.muon_AX           = pw.muon_X   + dectc::kDecMuonMaxNumel;
855	        pw.muon_AAX          = pw.muon_AX  + dectc::kDecMuonMaxNumel;
856	        pw.muon_orth         = pw.muon_AAX + dectc::kDecMuonMaxNumel;
857	        pw.muon_A            = pw.muon_orth + dectc::kDecMuonMaxNumel;
858	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)dectc::kDecMuonMaxRows * dectc::kDecMuonMaxRows;
859	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
860	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
861	        const int   ns_steps = 5;                 // bindings.cpp default
862	        for (int mi = 0; mi < dectc::kDecNumMuon2D; ++mi) {
863	            const dectc::DecMuon2D M = dectc::kDecMuon2D[mi];
864	            const int rows = M.rows, cols = M.cols;
865	            const int64_t numel = (int64_t)rows * cols;
866	            const int64_t off   = (int64_t)kDecOffsets[M.tidx];
867	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
868	            pw.muon_buf = st.exp_avg + off;
869	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
870	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
871	            bar.sync();
872	            muon_norm_reduce_phaseB(ctx, pw);
873	            bar.sync();
874	            muon_scale_X(numel, pw);
875	            bar.sync();
876	            // NS iterations. After each combine, orth holds the new iterate; swap so
877	            // the next iteration reads it as X. ns_steps swaps → final result is in
878	            // muon_X (the last combine wrote muon_orth, then we swapped → muon_X).
879	            for (int s = 0; s < ns_steps; ++s) {
880	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
881	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
882	                bar.sync();
883	                // AX = A X   (M=rows,N=cols,K=rows).
884	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
885	                bar.sync();
886	                // AAX = A (AX) (M=rows,N=cols,K=rows).
887	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
888	                bar.sync();
889	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
890	                bar.sync();
891	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
892	            }
893	            // Apply Muon: p = decay_factor·p + neg_lr_scale·orth  (muon.h:63-73).
894	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
895	            const float neg_lr_scale = -lr * scale;
896	            const float decay_factor = 1.0f - lr * st.wd;
897	            float* __restrict__ p = params + off;
898	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
899	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
900	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
901	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
902	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
903	        }
904	    }
905	
906	    // ── P2.45 (SuperGrok11/15 ONLY) staged into P3: the per-TENSOR meta-net mu
907	    //    precompute (INTEGRATION-OPTSTAGES §4/§5). SINGLE task-queue drain, NO grid
908	    //    barrier: each tensor T is SELF-CONTAINED — mu(T) = sg_rescale·phi(g[T],
909	    //    sharpness[T]) (per element) and, for SG11, the per-tensor gate(T) =
910	    //    sigmoid(gate_temp·cos(g[T], mu[T])) depend ONLY on T's own elements (never on any
911	    //    other tensor's mu), so mu(+gate)→apply fuse into ONE body the SAME CTA owns
912	    //    end-to-end inside the EXISTING P3 drain (every thread of a CTA claims the same
913	    //    tensor t via the block-level task_slot, so the helper's __syncthreads/block-
914	    //    reduce are block-uniform and safe). NOT a separate full-queue mu pre-pass +
915	    //    a second apply drain (that would silently no-op — see the SG11 block in
916	    //    opt_stages_precompute.cuh). The phi weights (per-TENSOR weight set) are staged
917	    //    to SMEM ONCE per block before the drain. SG15's gate is the host scalar st.gate
918	    //    (no cosine stage); SG11 binds the per-tensor gate the helper returns. sharpness
919	    //    (the 2nd MLP input) was produced by P2.4 (or the cached prior step).
920	    __shared__ float sg_sW1[kSgPhiHidden * 2];
921	    __shared__ float sg_sb1[kSgPhiHidden];
922	    __shared__ float sg_sW2[kSgPhiHidden];
923	    if constexpr (Opt == OptId::SuperGrok11 || Opt == OptId::SuperGrok15) {
924	        sg_stage_phi_weights<kSgPhiHidden>(st.sg_phi_W1, st.sg_phi_b1, st.sg_phi_W2,
925	                                           sg_sW1, sg_sb1, sg_sW2);   // syncs
926	    }
927	
928	    // ── P3-SG2 (SuperGrok2 ONLY): the FULL CSA/HCA/PEER/GRU meta-net as the
929	    //    optimizer phase, run INSTEAD of the per-element apply_optimizer<SuperGrok2>
930	    //    (which is only the Adam-on-smart_grad stub). Each CTA work-steals WHOLE
931	    //    tensors from the queue (reset at B2 / B2.4g) and runs sg2_meta_stages for
932	    //    each tensor end-to-end: STAGE -1 in-kernel segmented sort (|grad| ascending,
933	    //    index tie-break — strategy A) → S0..S5 (input-proj, CSA, HCA, GRU, PEER,
934	    //    apply). The SAM-written st.sharpness (P2.4, (g_sam−g)²) is the meta-net's 2nd
935	    //    MLP input (sharp_base). The meta-net WEIGHTS come from HBM (the 35 KB bundle
936	    //    does NOT fit smem alongside DecTcSmem under the 48 KB cap) — sg2_meta_stages
937	    //    is instantiated with WeightsT==SG2Weights + BuildSort=true. The per-tensor
938	    //    intermediates + the segmented-sort scratch live in this CTA's slice of the
939	    //    SG2 workspace (carve-LAST, after the LookSAM sam_grad). This whole phase is
940	    //    if-constexpr'd to SuperGrok2, so every other cell is byte-identical (no extra
941	    //    barrier/work). The kernel returns after this — no trailing grid barrier (each
942	    //    tensor is CTA-local; the standalone megakernel's trailing bar.sync was only to
943	    //    let a composing stage reset the queue, which there is none here).
944	    if constexpr (Opt == OptId::SuperGrok2) {
945	        // Reconstruct the SG2 weight bundle (HBM pointers) from the threaded fields.
946	        SG2Weights w2{
947	            st.sg2_input_proj_W, st.sg2_input_proj_b,
948	            st.sg2_csa_q_W, st.sg2_csa_k_W, st.sg2_csa_v_W, st.sg2_csa_out_W,
949	            st.sg2_csa_compress_w, st.sg2_csa_idx_DQ, st.sg2_csa_idx_K,
950	            st.sg2_hca_q_W, st.sg2_hca_k_W, st.sg2_hca_v_W, st.sg2_hca_out_W,
951	            st.sg2_gru_Wz, st.sg2_gru_bz, st.sg2_gru_Wr, st.sg2_gru_br,
952	            st.sg2_gru_Wh, st.sg2_gru_bh,
953	            st.sg2_peer_query_Ws, st.sg2_prod_keys_A, st.sg2_prod_keys_B,
954	            st.sg2_expert_W1, st.sg2_expert_b1, st.sg2_expert_W2, st.sg2_expert_b2};
955	        SG2Scalars sc2{
956	            st.sg2_alpha, st.sg2_gru_decay, st.sg2_lamb_eff,
957	            st.sg2_beta1, st.sg2_bc1, st.sg2_bc2,
958	            st.sg2_rescale, st.beta2, lr, st.wd, st.eps};
959	        // Stage row_off (int64) for the SG2State adapter once into the FRONT of this
960	        // CTA's SG2 workspace slice (kDecOffsets is __constant__ int; SG2State.row_off
961	        // wants const int64_t*). All CTAs stage their own copy (cheap, kDecNumTensors).
962	        float* sg2_base = sg2_ws_base + (int64_t)blockIdx.x * dec_sg2_ws_stride_floats();
963	        int64_t* row_off64 = reinterpret_cast<int64_t*>(sg2_base);
964	        for (int t = threadIdx.x; t < kDecNumTensors; t += blockDim.x)
965	            row_off64[t] = (int64_t)kDecOffsets[t];
966	        // The meta-net scratch starts AFTER the row_off64 staging block (rounded to
967	        // keep the carve's float alignment): reserve kDecNumTensors int64 = 2*N floats.
968	        float* sg2_meta_ws = sg2_base + 2 * kDecNumTensors;
969	        __syncthreads();
970	        SG2State stt{};
971	        stt.exp_avg     = st.exp_avg;
972	        stt.exp_avg_sq  = st.exp_avg_sq;
973	        stt.mu          = const_cast<float*>(st.mu);
974	        stt.slow        = st.sg2_slow;
975	        stt.gru_state   = st.sg2_gru_state;
976	        stt.perm        = nullptr;          // built in-kernel (BuildSort=true)
977	        stt.unsort      = nullptr;
978	        stt.workspace   = sg2_meta_ws;
979	        stt.ws_stride   = sg2_ws_stride<DecSG2Dims>((int64_t)kDecSG2Nmax);
980	        stt.n_tensors   = kDecNumTensors;
981	        stt.n           = kDecSizes;        // __constant__ int[]
982	        stt.row_off     = row_off64;
983	        __shared__ int task_slot2;
984	        TaskQueue q2 = ctx.queue();
985	        for (int t = q2.next_block(&task_slot2); t < kDecNumTensors;
986	             t = q2.next_block(&task_slot2)) {
987	            sg2_meta_stages<DecSG2Dims, SG2Weights, float, float, /*BuildSort=*/true>(
988	                w2, t, stt, sc2, params, grad, st.sharpness, sg2_meta_ws);
989	        }
990	        return;   // SG2 owns the whole optimizer phase; skip P3.
991	    }
992	
993	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal the 30
994	    //    tensors). apply_optimizer<Opt> is the canonical csrc/algorithms math. ──
995	    st.lr = lr;
996	    {
997	        __shared__ int task_slot;
998	        TaskQueue q = ctx.queue();
999	        for (int t = q.next_block(&task_slot); t < kDecNumTensors;
1000	             t = q.next_block(&task_slot)) {
1001	            const int n = kDecSizes[t];
1002	            const int64_t off = (int64_t)kDecOffsets[t];
1003	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
1004	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
1005	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
1006	            if constexpr (Opt == OptId::Muon) {
1007	                if (dectc::dec_is_muon_2d(t)) continue;
1008	            }
1009	            FusedOptState ts = rebase_state<Opt>(st, off);
1010	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only): β1_i = β1·(1-γ)^t,
1011	            //     t == the tensor's flat named_parameters() layer index (the
1012	            //     work-steal task id maps 1:1 to kDecOffsets order == the eager
1013	            //     enumeration order, so t IS the eager layer index). bc1 must be
1014	            //     rebased TOO (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager
1015	            //     (~9.6× on the deepest layer); bc2 stays global (β2 not layer-wise).
1016	            if constexpr (Opt == OptId::GrokAdamW) {
1017	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
1018	                ts.beta1 = b1;
1019	                ts.bc1   = 1.0f - powf(b1, (float)step);
1020	            }
1021	            // SuperGrok11/15 meta-net mu (+ SG11 per-tensor gate) precompute for THIS
1022	            // tensor, BEFORE the apply reads ts.mu/ts.gate. mu(T)=sg_rescale·phi(g,
1023	            // sharpness) over [off,off+n); SG11 also computes the gate(T)=sigmoid(gate_temp·cos)
1024	            // (block-uniform __syncthreads/reduce — the whole CTA owns t). SG15's gate is
1025	            // st.gate (host sigmoid(accuracy)). Helpers index grad/sharpness/mu by off+i,
1026	            // so pass the BASE pointers (st.mu, grad, st.sharpness) + off; the apply then
1027	            // reads ts.mu (== st.mu+off). phi_b2 read on-device from sg_phi_W2[H].
1028	            if constexpr (Opt == OptId::SuperGrok11) {
1029	                const float b2 = (st.sg_phi_W2 != nullptr) ? st.sg_phi_W2[kSgPhiHidden]
1030	                                                           : st.sg_phi_b2;
1031	                const float g8 = sg11_precompute_mu_and_gate_for_tensor<kSgPhiHidden>(
1032	                    st.mu, grad, st.sharpness, sg_sW1, sg_sb1, sg_sW2,
1033	                    b2, st.sg_rescale, off, n, st.gate_temp);
1034	                ts.gate = g8;            // per-tensor gate=sigmoid(gate_temp·cos) the apply tail reads
1035	                __syncthreads();         // mu(T) fully written + gate broadcast before apply
1036	            } else if constexpr (Opt == OptId::SuperGrok15) {
1037	                const float b2 = (st.sg_phi_W2 != nullptr) ? st.sg_phi_W2[kSgPhiHidden]
1038	                                                           : st.sg_phi_b2;
1039	                sg15_precompute_mu_for_tensor<kSgPhiHidden>(
1040	                    st.mu, grad, st.sharpness, sg_sW1, sg_sb1, sg_sW2,
1041	                    b2, st.sg_rescale, off, n);
1042	                // ts.gate stays = st.gate (the host sigmoid(accuracy) scalar).
1043	                __syncthreads();         // mu(T) visible before the apply reads it
1044	            }
1045	            float* __restrict__ p = params + off;
1046	            const float* __restrict__ gg = grad + off;
1047	            if constexpr (Opt == OptId::Muon) {
1048	                // 1D / non-2D weights: the canonical AdamW tail (muon.py:99-125 routes
1049	                // non-matrix params to a SEPARATE AdamW group with INDEPENDENT
1050	                // hyperparameters — adamw_lr/adamw_betas — NOT the 2D Muon lr/momentum).
1051	                // ts.lr/ts.beta1 carry the 2D-group's (lr=0.02, momentum=0.95), so the
1052	                // 1D tail MUST instead use the aux_* fields (eager adamw_lr/adamw_betas).
1053	                // weight_decay is SHARED across both eager groups (muon.py:122) → ts.wd
1054	                // stays. eps is the eager adamw_eps (= ts.eps, mapped by _opt_scalars_from).
1055	                // bc1/bc2 are device-computed from aux_beta^step (kept out of the mirror
1056	                // to shrink the host ABI; fp32 powf, tol 2e-3 ample). apply_optimizer<Muon>
1057	                // would deref st.orth (NS dir, only valid for 2D), so route directly to
1058	                // adamw_step with the aux hyperparameters — IDENTICAL to the vit twin.
1059	                const float a_bc1 = 1.0f - powf(st.aux_beta1, (float)step);
1060	                const float a_bc2 = 1.0f - powf(st.aux_beta2, (float)step);
1061	                for (int i = threadIdx.x; i < n; i += blockDim.x)
